import com.smartmanager.nativeapp.*;
public class BatchArchiveTest { public static void main(String[]x){BatchArchive a=new BatchArchive();a.put("r1-b1","one");a.put("r2-b1","two");BatchArchive b=BatchArchive.decode(a.encode());if(b.ids().size()!=2||!"two".equals(b.get("r2-b1")))throw new AssertionError("archive");try{BatchArchive.decode("BATCH-ARCHIVE-1\ncorrupt");throw new AssertionError("corrupt accepted");}catch(IllegalArgumentException ok){}try{a.put("r1-b1","x");throw new AssertionError("duplicate");}catch(IllegalArgumentException ok){}System.out.println("PASS: multi-batch archive, migration-safe corruption rejection and duplicate IDs");} }
